#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

struct BabyRecord {
    int rank;
    std::string boyName;
    int boyCount;
    std::string girlName;
    int girlCount;
};

int cleanAndParseInt(std::string s) {
    std::string clean; for(char ch:s)if(ch!=',')clean+=ch;s=clean;
    return std::stoi(s);
}

int main() {
    int n;
    if (!(std::cin >> n)) return 0;

    std::vector<BabyRecord> records;
    for (int i = 0; i < n; ++i) {
        int rank;
        std::string boy, boyCnt, girl, girlCnt;
        if (std::cin >> rank >> boy >> boyCnt >> girl >> girlCnt) {
            records.push_back({rank, boy, cleanAndParseInt(boyCnt), girl, cleanAndParseInt(girlCnt)});
        }
    }

    for (const auto& r : records) {
        std::cout << "Rank #" << r.rank << ": Boy=" << r.boyName 
                  << " (" << r.boyCount << "), Girl=" << r.girlName 
                  << " (" << r.girlCount << ")\n";
    }

    // Verify whether boy names are stored in alphabetical order
    bool sorted = true;
    for (size_t i = 1; i < records.size(); ++i) {
        if (records[i - 1].boyName > records[i].boyName) {
            std::cout << "Out of order: " << records[i - 1].boyName 
                      << " > " << records[i].boyName << "\n";
            sorted = false;
            break;
        }
    }
    if (sorted && !records.empty()) {
        std::cout << "Boy names are sorted.\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <type_traits>
#include <cstdint>

// Trivially copyable POD struct representing Loan (Listing 9.13)
struct Loan {
    double annualInterestRate;
    int numberOfYears;
    double loanAmount;
};

static_assert(std::is_trivially_copyable<Loan>::value, "byte copy requires trivially copyable type");
int main() {
    int count;
    if (!(std::cin >> count)) return 0;

    std::vector<Loan> originalLoans;
    for (int i = 0; i < count; ++i) {
        Loan l;
        std::cin >> l.annualInterestRate >> l.numberOfYears >> l.loanAmount;
        originalLoans.push_back(l);
    }

    // Simulate binary buffer packing (serialization)
    std::vector<char> binaryBuffer;
    binaryBuffer.resize(originalLoans.size() * sizeof(Loan));

    for (size_t i = 0; i < originalLoans.size(); ++i) {
        const char* bytePtr = reinterpret_cast<const char*>(&originalLoans[i]);
        std::copy(bytePtr, bytePtr + sizeof(Loan), binaryBuffer.begin() + i * sizeof(Loan));
    }

    // Deserialize objects back from binary buffer
    double totalAmount = 0.0;
    size_t restoredCount = 0;
    size_t offset = 0;

    while (offset + sizeof(Loan) <= binaryBuffer.size()) {
        Loan temp;
        char* destPtr = reinterpret_cast<char*>(&temp);
        std::copy(binaryBuffer.begin() + offset, binaryBuffer.begin() + offset + sizeof(Loan), destPtr);

        totalAmount += temp.loanAmount;
        restoredCount++;
        offset += sizeof(Loan);
    }

    std::cout << "Restored " << restoredCount << " loans. Total amount: $" 
              << totalAmount << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <cstdint>

std::vector<uint8_t> encryptBytes(const std::string& input) {
    std::vector<uint8_t> output(input.size());
    for (size_t i = 0; i < input.size(); ++i) {
        output[i] = static_cast<uint8_t>(static_cast<uint8_t>(input[i]) + static_cast<uint8_t>(i));
    }
    return output;
}

std::string decryptBytes(const std::vector<uint8_t>& input) {
    std::string output(input.size(), '\0');
    for (size_t i = 0; i < input.size(); ++i) {
        output[i] = static_cast<char>(static_cast<uint8_t>(input[i] - static_cast<uint8_t>(i)));
    }
    return output;
}

int main() {
    std::string text;
    int runsToAdd;
    if (!(std::cin >> text >> runsToAdd)) return 0;

    // 1. Demonstrate byte-index encryption / decryption
    std::vector<uint8_t> encrypted = encryptBytes(text);
    std::string decrypted = decryptBytes(encrypted);
    std::cout << "Decrypted successfully: " << decrypted << "\n";

    // 2. Simulate in-place execution counter
    int runCount = 0;
    for (int r = 0; r < runsToAdd; ++r) {
        runCount++;
    }
    std::cout << "Current execution count: " << runCount << "\n";

    return 0;
}
